package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code householdSize} on create: the number of owners sharing the same
 * household once this owner is counted. The household is keyed on the deterministic
 * {@code householdId} (normalized last name and postcode — see {@link HouseholdKey}), so a member
 * is any other owner that computes the same id.
 *
 * <p>The new owner is not yet saved, so it is counted by adding one to the existing same-household
 * members. A fully-unique owner (no other owner shares its last name and postcode) is therefore a
 * household of one.
 */
public class CountHouseholdMembers {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = HouseholdKey.of(owner).householdId();
        int existing = (int) ownerRepository.findAll().stream()
                .filter(existingOwner -> existingOwner.getId() == null
                        || !existingOwner.getId().equals(owner.getId()))
                .filter(existingOwner -> householdId.equals(HouseholdKey.of(existingOwner).householdId()))
                .count();
        owner.setHouseholdSize(existing + 1);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;
import java.util.Objects;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The identity of a household: the same last name and the same postcode. The last name is
 * compared case-insensitively with whitespace trimmed and collapsed; the postcode is compared
 * as stored. So e.g. "  Smith " at postcode "2000" is the same household as "smith" at "2000".
 *
 * <p>Single-sources the "what is a household" definition. The {@code householdId} is derived
 * <em>deterministically</em> from this key (see {@link #householdId()}): the first 12 hex
 * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Every owner computes
 * the same id for the same household automatically, so two owners share a {@code householdId}
 * exactly when they share a last name and postcode — no opt-in and no back-filling required.
 */
final class HouseholdKey {

    private final String lastName;

    private final String postcode;

    private HouseholdKey(String lastName, String postcode) {
        this.lastName = lastName;
        this.postcode = postcode;
    }

    /** The household the given owner belongs to. */
    static HouseholdKey of(Owner owner) {
        return new HouseholdKey(normalize(owner.getLastName()), owner.getPostcode() == null ? "" : owner.getPostcode());
    }

    /** Whether {@code owner} belongs to this household. */
    boolean matches(Owner owner) {
        return equals(of(owner));
    }

    /** Stable canonical form of the key, suitable for deriving a shared identifier. */
    String canonical() {
        return lastName + "|" + postcode;
    }

    /**
     * The deterministic {@code householdId} for this household: the first 12 hex characters of
     * SHA-256 over {@link #canonical()}. Owners with the same last name and postcode compute the
     * same value, so they share a household automatically.
     */
    String householdId() {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(canonical().getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof HouseholdKey other)) {
            return false;
        }
        return lastName.equals(other.lastName) && postcode.equals(other.postcode);
    }

    @Override
    public int hashCode() {
        return Objects.hash(lastName, postcode);
    }

    @Override
    public String toString() {
        return canonical();
    }

    /** Lower-case, trim, and collapse any run of whitespace to a single space. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256
 * over the household key (normalized last name and postcode — see {@link HouseholdKey}). Every
 * owner is assigned one unconditionally, so owners with the same last name and postcode share the
 * same id automatically, with no opt-in and no back-filling of other owners.
 *
 * <p>The {@code sharesHousehold} create-time flag no longer plays any part here; it only tells
 * {@link RejectDuplicateIdentity} to let a declared household member through the duplicate block.
 * Runs before {@link RejectDuplicateIdentity} and {@link CountHouseholdMembers}, both of which key
 * off this id.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(HouseholdKey.of(owner).householdId());
    }
}
